  const proceedToRegistration = () => {
    setCurrentStep(1);
    setShowSystemResponse(false);
    addNotification('📝 Proceeding to Registration...');
  };

  // ============================================
  // GO TO NEXT STEP (Registration)
  // ============================================
  const goToNextStep = async () => {
    const step = currentStep + 1;

    if (userExistsError) {
      setShowMainMenu(true);
      setIsLoggedIn(true);
      setUserExistsError(false);
      setRegistrationError('');
      return;
    }

    if (step === 2) {
      // --- Validate phone number ---
      if (!formData.phone_number || !validateKenyanPhone(formData.phone_number.trim())) {
        setRegistrationError('❌ Please enter a valid Kenyan phone number (e.g. 0712345678).');
        return;
      }
      // --- Validate age >= 18 ---
      const ageNum = parseInt(formData.age, 10);
      if (!formData.age || isNaN(ageNum) || ageNum < 18) {
        setRegistrationError('❌ You must be at least 18 years old to register.');
        return;
      }
      // --- Validate password ---
      const pwd = formData.password || '';
      const strongPwdRegex = /^(?=.*[a-zA-Z])(?=.*[0-9\W]).{10,}$/;
      if (!strongPwdRegex.test(pwd)) {
        setRegistrationError('❌ Password must be at least 10 characters and contain letters and numbers/symbols.');
        return;
      }

      setRegistrationError('');
      setIsLoading(true);
      try {
        const data = {
          phone_number: formData.phone_number,
          name: formData.name,
          password: formData.password,
          age: formData.age,
          gender: formData.gender,
          county: formData.county,
          town: formData.town
        };

        const result = await callApi('/register', 'POST', data);

        if (result && result.status === 'error' && result.message === 'User already exists') {
          setRegistrationError('⚠️ An account already exists with this phone number.');
          setUserExistsError(true);
          addNotification('⚠️ User already exists.', 'warning');

          const partialUser = {
            phone: formData.phone_number || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi',
            gender: formData.gender || 'Male'
          };
          setCurrentUser(partialUser);
          setMyPhone(formData.phone_number || '0712345678');
          setIsLoading(false);
          return;
        }

        if (result && result.status === 'success') {
          const userMsg = `start#${formData.name}#${formData.age}#${formData.gender}#${formData.county}#${formData.town}`;
          addToConversation('📱 You', userMsg, false);
          addToConversation('🤖 System', SYSTEM_MESSAGES.registrationSuccess(formData.name || 'User'), true);

          setSystemResponseMessage(SYSTEM_MESSAGES.registrationSuccess(formData.name || 'User'));
          setShowSystemResponse(true);
          setMyPhone(formData.phone_number || '0712345678');
          setCompletedSteps(prev => new Set([...prev, 1]));
          addNotification('✅ Registration complete!');

          const newUser = {
            phone: formData.phone_number || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi',
            gender: formData.gender || 'Male'
          };
          setCurrentUser(newUser);
          setCurrentStep(3);
          // Show success with auto-redirect (no buttons)
          setSuccessTitle('🎉 Congratulations!');
          setSuccessMessage('Your account has been successfully created. You may now complete your dating profile.');
          setSuccessCountdown(3);
          setSuccessRedirecting(true);
          setShowSuccessScreen(true);
          setIsLoading(false);
          return;
        } else {
          const errorMsg = result?.message || 'Registration failed. Please try again.';
          setRegistrationError(errorMsg);
          addNotification('❌ ' + errorMsg, 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Registration error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    if (step === 3) {
      setIsCompleteProfileStep(true);
      setCurrentStep(3);
      setIsLoading(false);
      return;
    }

    if (step === 4) {
      setIsLoading(true);
      try {
        const phone = currentUser?.phone || myPhone || '0712345678';
        const result = await callApi(`/${phone}/self-description`, 'POST', { 
          description: formData.description 
        });

        if (result && result.status === 'success') {
          addToConversation('📱 You', `MYSELF ${formData.description}`, false);
          addToConversation('🤖 System', SYSTEM_MESSAGES.selfDescriptionSuccess, true);

          setSystemResponseMessage(SYSTEM_MESSAGES.selfDescriptionSuccess);
          setShowSystemResponse(true);
          setCompletedSteps(prev => new Set([...prev, 3]));
          setRegistrationComplete(true);
          addNotification('✅ Registration complete!');

          if (currentUser) {
            setCurrentUser(prev => ({
              ...prev,
              description: formData.description
            }));
          }

          setSuccessTitle('🎉 Registration Complete!');
          setSuccessMessage('You are now registered for dating!\n\nTo search for a MPENZI, use the search feature and meet the person of your dreams.');
          setSuccessCountdown(3);
          setSuccessRedirecting(true);
          setShowSuccessScreen(true);
          setIsFirstTimeUser(false);
          setIsLoading(false);
          return;
        } else {
          setRegistrationError(result?.message || 'Self-description failed.');
          addNotification('❌ Self-description failed.', 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Self-description error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    if (step <= 4) {
      setCurrentStep(step);
    }
  };

  // ============================================
  // SAVE COMPLETE PROFILE (Step 3)
  // ============================================
  const saveCompleteProfile = async () => {
    const requiredFields = ['education_level', 'profession', 'marital_status', 'religion', 'ethnicity'];
    const hasRequired = requiredFields.every(f => formData[f] && formData[f].trim() !== '');

    if (!hasRequired) {
      addNotification('⚠️ Please fill in all fields.', 'warning');
      return;
    }

    setIsLoading(true);
    try {
      const phone = currentUser?.phone || myPhone || '0712345678';
      const data = {
        education_level: formData.education_level,
        profession: formData.profession,
        marital_status: formData.marital_status,
        religion: formData.religion,
        ethnicity: formData.ethnicity
      };

      const result = await callApi(`/${phone}/complete-profile`, 'POST', data);

      if (result && result.status === 'success') {
        const userMsg = `details#${formData.education_level}#${formData.profession}#${formData.marital_status}#${formData.religion}#${formData.ethnicity}`;
        addToConversation('📱 You', userMsg, false);
        addToConversation('🤖 System', SYSTEM_MESSAGES.detailsProvided, true);

        setSystemResponseMessage(SYSTEM_MESSAGES.detailsProvided);
        setShowSystemResponse(true);

        setCompletedSteps(prev => new Set([...prev, 2]));
        addNotification('✅ Profile completed successfully!');

        if (currentUser) {
          setCurrentUser(prev => ({
            ...prev,
            ...data
          }));
        }

        setCurrentStep(4);
        setIsCompleteProfileStep(false);
        setIsLoading(false);
      } else {
        setRegistrationError(result?.message || 'Failed to save profile.');
        addNotification('❌ Failed to save profile.', 'error');
        setIsLoading(false);
      }
    } catch (error) {
      console.error('Save profile error:', error);
      setRegistrationError('Network error. Please try again.');
      addNotification('❌ Network error', 'error');
      setIsLoading(false);
    }
  };

